CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('customer','admin') NOT NULL DEFAULT 'customer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cj_pid VARCHAR(100) NULL, cj_vid VARCHAR(100) NOT NULL, sku VARCHAR(100) NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, image_url TEXT NULL, supplier_cost DECIMAL(12,2) NOT NULL DEFAULT 0, price DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(active), UNIQUE KEY uq_cj_vid(cj_vid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(40) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, customer_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(50) NOT NULL, address1 VARCHAR(255) NOT NULL, address2 VARCHAR(255) NULL, city VARCHAR(120) NOT NULL, province VARCHAR(120) NOT NULL, postal_code VARCHAR(30) NULL, country VARCHAR(100) NOT NULL, country_code CHAR(2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, supplier_cost_total DECIMAL(12,2) NOT NULL DEFAULT 0, profit_estimate DECIMAL(12,2) NOT NULL DEFAULT 0, payment_status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending', fulfilment_status ENUM('awaiting_payment','pending','submitted','failed','shipped','delivered','cancelled') NOT NULL DEFAULT 'awaiting_payment', paypal_order_id VARCHAR(120) NULL, cj_order_id VARCHAR(120) NULL, cj_response TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(user_id), INDEX(payment_status), INDEX(fulfilment_status), CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, cj_vid VARCHAR(100) NOT NULL, title VARCHAR(255) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(12,2) NOT NULL, supplier_cost DECIMAL(12,2) NOT NULL, line_total DECIMAL(12,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, CONSTRAINT fk_items_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
